// Quiz functionality
let currentQuestion = 0;
let correctAnswers = 0;

function displayQuestion() {
    const container = document.getElementById('quiz-container');
    if (currentQuestion >= quizQuestions.length) {
        showSummary();
        return;
    }

    const q = quizQuestions[currentQuestion];
    container.innerHTML = `
        <div class="quiz-question">
            <h3>Question ${currentQuestion + 1} of ${quizQuestions.length}</h3>
            <p>${q.question}</p>
            <div class="quiz-options">
                ${q.options.map((option, index) => `
                    <button class="quiz-option" onclick="checkAnswer(${index})">${option}</button>
                `).join('')}
            </div>
            <div class="feedback" id="feedback"></div>
        </div>
    `;
}

function checkAnswer(selected) {
    const q = quizQuestions[currentQuestion];
    const buttons = document.querySelectorAll('.quiz-option');
    const feedback = document.getElementById('feedback');

    buttons.forEach((btn, idx) => {
        btn.disabled = true;
        if (idx === q.correct) {
            btn.classList.add('correct');
        } else if (idx === selected && selected !== q.correct) {
            btn.classList.add('wrong');
        }
    });

    if (selected === q.correct) {
        correctAnswers++;
        feedback.className = 'feedback correct show';
        feedback.innerHTML = `<strong>✓ Correct!</strong><br><br>${q.explanation}`;
    } else {
        feedback.className = 'feedback wrong show';
        feedback.innerHTML = `<strong>✗ Incorrect.</strong><br><br>${q.explanation}`;
    }

    setTimeout(() => {
        currentQuestion++;
        displayQuestion();
    }, 8000);
}

function showSummary() {
    const container = document.getElementById('quiz-container');
    const summary = document.getElementById('quiz-summary');
    const score = document.getElementById('quiz-score');

    container.style.display = 'none';
    summary.style.display = 'block';

    const percentage = Math.round((correctAnswers / quizQuestions.length) * 100);
    score.innerHTML = `You scored ${correctAnswers} out of ${quizQuestions.length} (${percentage}%)`;

    if (percentage >= 90) {
        score.innerHTML += '<br><br>🎉 Excellent! You have a strong understanding of DeepSeek-R1\'s RL-based reasoning approach.';
    } else if (percentage >= 70) {
        score.innerHTML += '<br><br>👍 Good work! You understand the core concepts. Review the sections on reward design and the multi-stage pipeline for deeper insight.';
    } else {
        score.innerHTML += '<br><br>📚 Keep learning! Review the lesson content, especially the sections on pure RL vs SFT+RL, emergent behaviors, and reward hacking.';
    }
}

// Initialize quiz on page load
document.addEventListener('DOMContentLoaded', () => {
    if (document.getElementById('quiz-container')) {
        displayQuestion();
    }
});
